# src/auth.py
def validate_token(payload, now):
    expires_at = payload.get('expires_at')
    if expires_at is None:
        return False
    return expires_at >= now

def parse_expiry(value):
    parsed = datetime.fromisoformat(value.replace('Z', '+00:00'))
    if parsed.tzinfo is None:
        raise ValueError('expiry must include timezone')
    return parsed

调用方会把 ISO-8601 字符串转换为 timezone-aware datetime。当前实现的边界条件可能错误：expires_at 等于 now 时仍会通过。调用链还会记录认证失败原因，但不会把 token 内容写入日志；这一约束不需要在本次修改中变更。

from decimal import Decimal

def aggregate(lines):
    total = sum((line.price for line in lines), Decimal('0'))
    return {'count': len(lines), 'total': str(total)}
